// The PayPal client. Sandbox only (hard rule 7), and every POST carries a PayPal-Request-Id that the caller generated
// and stored on its payment row before calling (hard rule 4): there is no default, so a retry replays the same id.
// Orders and Payments go through PayPal's server SDK (@paypal/paypal-server-sdk, generated by APIMatic); Payouts,
// Invoicing and webhook verification are not in that SDK, so a small fetch client shares the same cached token.
// Never logged: the token, the client secret, request bodies with emails. PayPal's debug_id is what we keep.

import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  CustomError,
  Environment,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";
import type { ApiResponse, OAuthToken } from "@paypal/paypal-server-sdk";
import { assertSandbox } from "@/lib/env";
import { toAmount } from "@/lib/money";

const BASE_URL = "https://api-m.sandbox.paypal.com";

export class PayPalError extends Error {
  constructor(
    readonly status: number,
    /** PayPal's issue name (details[0].issue, else name), e.g. AUTHORIZATION_VOIDED. */
    readonly issue: string,
    readonly debugId: string | undefined,
    /** HATEOAS links on the error, e.g. to the batch an already-used sender_batch_id created. */
    readonly links: { href: string; rel?: string }[] = [],
    /** PayPal's top-level error name, e.g. USER_BUSINESS_ERROR, when the issue is a detail under it. */
    readonly errorName?: string,
  ) {
    super(`PayPal ${status} ${issue}${debugId ? ` (debug_id ${debugId})` : ""}`);
    this.name = "PayPalError";
  }
}

function credentials() {
  assertSandbox();
  const id = process.env.PAYPAL_CLIENT_ID;
  const secret = process.env.PAYPAL_CLIENT_SECRET;
  if (!id || !secret) throw new Error("PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET must be set");
  return { id, secret };
}

// One token per process, shared by the SDK and the fetch client. PayPal hands back the same token until it expires;
// refresh a minute early. Kept on globalThis so `next dev` reloads don't mint a token per edit.
// Tests replay recorded sandbox responses instead of calling PayPal (tests never call live APIs): the SDK through a
// stub axios adapter (its documented seam, `unstable_httpClientOptions`) with a seeded token, REST through `fetch`.
type AxiosAdapter = (config: { url: string; method: string; data?: string }) => Promise<unknown>;
let testTransport: { adapter: AxiosAdapter; fetch: typeof fetch } | null = null;

export function setPayPalTransportForTests(transport: { adapter: AxiosAdapter; fetch: typeof fetch } | null): void {
  testTransport = transport;
  shared.paypalSdk = undefined;
  shared.paypalToken = transport ? { value: "test-token", expiresAt: Date.now() + 3_600_000 } : undefined;
}

const shared = globalThis as typeof globalThis & {
  paypalToken?: { value: string; expiresAt: number };
  paypalTokenInFlight?: Promise<{ value: string; expiresAt: number }>;
  paypalSdk?: Client;
};

async function token(): Promise<{ value: string; expiresAt: number }> {
  const cached = shared.paypalToken;
  if (cached && Date.now() < cached.expiresAt - 60_000) return cached;
  shared.paypalTokenInFlight ??= (async () => {
    const { id, secret } = credentials();
    const res = await fetch(`${BASE_URL}/v1/oauth2/token`, {
      method: "POST",
      headers: {
        Authorization: `Basic ${Buffer.from(`${id}:${secret}`).toString("base64")}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: "grant_type=client_credentials",
    });
    const body = (await res.json().catch(() => ({}))) as { access_token?: string; expires_in?: number; error?: string };
    if (!res.ok || !body.access_token) {
      throw new PayPalError(res.status, body.error ?? "TOKEN_FAILED", res.headers.get("paypal-debug-id") ?? undefined);
    }
    const fresh = { value: body.access_token, expiresAt: Date.now() + (body.expires_in ?? 0) * 1000 };
    shared.paypalToken = fresh;
    return fresh;
  })().finally(() => {
    shared.paypalTokenInFlight = undefined;
  });
  return shared.paypalTokenInFlight;
}

export function sdk(): Client {
  const { id, secret } = credentials();
  shared.paypalSdk ??= new Client({
    environment: Environment.Sandbox,
    timeout: 30_000,
    // No SDK retries (its default too): our callers retry with the same stored request id, so PayPal dedupes.
    httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } },
    ...(testTransport ? { unstable_httpClientOptions: { adapter: testTransport.adapter } } : {}),
    clientCredentialsAuthCredentials: {
      oAuthClientId: id,
      oAuthClientSecret: secret,
      // Must never reject: the SDK would cache the rejection and fail every later call. On failure, hand back an
      // expired token; that one call fails and the next asks again.
      oAuthTokenProvider: async (): Promise<OAuthToken> => {
        try {
          const t = await token();
          return { accessToken: t.value, tokenType: "Bearer", expiry: BigInt(Math.floor(t.expiresAt / 1000)) };
        } catch {
          return { accessToken: "", tokenType: "Bearer", expiry: BigInt(0) };
        }
      },
    },
  });
  return shared.paypalSdk;
}

/** Runs one SDK call and turns PayPal's error payload into a PayPalError. */
export async function call<T>(run: () => Promise<ApiResponse<T>>): Promise<{ status: number; result: T; debugId?: string }> {
  try {
    const response = await run();
    return { status: response.statusCode, result: response.result, debugId: response.headers["paypal-debug-id"] };
  } catch (err) {
    // The SDK parses the error body onto `result` only for the statuses it lists for that call; any other (a 403 on
    // create order, measured 9 Nov) arrives with the body unparsed, so read it from there.
    if (err instanceof CustomError && err.result) {
      const r = err.result;
      throw new PayPalError(err.statusCode, r.details?.[0]?.issue ?? r.name ?? "UNKNOWN", r.debug_id ?? err.headers["paypal-debug-id"]);
    }
    if (err instanceof ApiError) {
      let parsed: { name?: string; debug_id?: string; details?: { issue?: string }[] } = {};
      try {
        parsed = JSON.parse(String(err.body));
      } catch {}
      throw new PayPalError(err.statusCode, parsed.details?.[0]?.issue ?? parsed.name ?? "UNKNOWN", parsed.debug_id ?? err.headers["paypal-debug-id"]);
    }
    throw err;
  }
}

export function requireRequestId(requestId: string) {
  if (!requestId || requestId.length > 38) throw new Error("every PayPal POST needs a stored PayPal-Request-Id of 1-38 characters");
}

const usd = (cents: number) => ({ currencyCode: "USD", value: toAmount(cents) });

// ---- Orders and Payments (server SDK) ----

/** An AUTHORIZE order to Second Look for one of Margaret's bills. She approves it on PayPal; we authorize after. */
export async function createAuthorizeOrder(input: {
  requestId: string;
  amountCents: number;
  description: string;
  customId: string;
  returnUrl: string;
  cancelUrl: string;
}): Promise<{ orderId: string; status: string; approveUrl: string; debugId?: string }> {
  requireRequestId(input.requestId);
  const { result, debugId } = await call(() =>
    new OrdersController(sdk()).createOrder({
      paypalRequestId: input.requestId,
      prefer: "return=representation",
      body: {
        intent: CheckoutPaymentIntent.Authorize,
        purchaseUnits: [
          {
            referenceId: input.customId,
            customId: input.customId,
            description: input.description.slice(0, 127),
            amount: usd(input.amountCents),
          },
        ],
        paymentSource: {
          paypal: {
            experienceContext: {
              brandName: "Second Look",
              shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
              userAction: PaypalExperienceUserAction.Continue,
              returnUrl: input.returnUrl,
              cancelUrl: input.cancelUrl,
            },
          },
        },
      },
    }),
  );
  const approveUrl = result.links?.find((l) => l.rel === "payer-action" || l.rel === "approve")?.href;
  if (!result.id || !approveUrl) throw new PayPalError(201, "NO_APPROVAL_LINK", debugId);
  return { orderId: result.id, status: String(result.status), approveUrl, debugId };
}

export async function getOrderStatus(orderId: string): Promise<string> {
  const { result } = await call(() => new OrdersController(sdk()).getOrder({ id: orderId }));
  return String(result.status);
}

/** After Margaret approved: places the hold. Nothing is taken until a capture. */
export async function authorizeOrder(input: { orderId: string; requestId: string }): Promise<{
  authorizationId: string;
  status: string;
  expiresAt: string | undefined;
  debugId?: string;
}> {
  requireRequestId(input.requestId);
  const { result, debugId } = await call(() =>
    new OrdersController(sdk()).authorizeOrder({ id: input.orderId, paypalRequestId: input.requestId, prefer: "return=representation" }),
  );
  const authorization = result.purchaseUnits?.[0]?.payments?.authorizations?.[0];
  if (!authorization?.id) throw new PayPalError(201, "NO_AUTHORIZATION", debugId);
  return { authorizationId: authorization.id, status: String(authorization.status), expiresAt: authorization.expirationTime, debugId };
}

/** Takes the held money (hard rule 1: only for auto-approved bills or after a family member approved). */
export async function captureAuthorization(input: { authorizationId: string; requestId: string; invoiceId: string }): Promise<{
  captureId: string;
  status: string;
  debugId?: string;
}> {
  requireRequestId(input.requestId);
  const { result, debugId } = await call(() =>
    new PaymentsController(sdk()).captureAuthorizedPayment({
      authorizationId: input.authorizationId,
      paypalRequestId: input.requestId,
      prefer: "return=representation",
      body: { finalCapture: true, invoiceId: input.invoiceId },
    }),
  );
  if (!result.id) throw new PayPalError(201, "NO_CAPTURE", debugId);
  return { captureId: result.id, status: String(result.status), debugId };
}

/** Releases the hold: the money never left. PREVIOUSLY_VOIDED counts as already released. */
export async function voidAuthorization(input: { authorizationId: string; requestId: string }): Promise<{ status: string; debugId?: string }> {
  requireRequestId(input.requestId);
  try {
    const { result, debugId } = await call(() =>
      new PaymentsController(sdk()).voidPayment({ authorizationId: input.authorizationId, paypalRequestId: input.requestId, prefer: "return=representation" }),
    );
    return { status: result?.status ? String(result.status) : "VOIDED", debugId };
  } catch (err) {
    if (err instanceof PayPalError && err.issue === "PREVIOUSLY_VOIDED") return { status: "VOIDED", debugId: err.debugId };
    throw err;
  }
}

// ---- Payouts (REST; not in the server SDK) ----

async function rest<T>(method: "GET" | "POST", path: string, opts: { body?: unknown; requestId?: string } = {}): Promise<{ status: number; body: T; debugId?: string }> {
  if (method === "POST") requireRequestId(opts.requestId ?? "");
  const t = await token();
  const res = await (testTransport?.fetch ?? fetch)(`${BASE_URL}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${t.value}`,
      "Content-Type": "application/json",
      Prefer: "return=representation",
      ...(opts.requestId ? { "PayPal-Request-Id": opts.requestId } : {}),
    },
    body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
    signal: AbortSignal.timeout(30_000),
  });
  const body = (await res.json().catch(() => ({}))) as T & {
    name?: string;
    debug_id?: string;
    details?: { issue?: string; link?: { href: string; rel?: string }[] }[];
    links?: { href: string; rel?: string }[];
  };
  const debugId = res.headers.get("paypal-debug-id") ?? body.debug_id;
  if (!res.ok) {
    const links = [...(body.links ?? []), ...(body.details ?? []).flatMap((d) => d.link ?? [])];
    throw new PayPalError(res.status, body.details?.[0]?.issue ?? body.name ?? "UNKNOWN", debugId, links, body.name);
  }
  return { status: res.status, body, debugId };
}

interface PayoutBatch {
  batch_header?: { payout_batch_id?: string; batch_status?: string };
}

/**
 * Pays one person from Second Look's balance. `senderBatchId` is the idempotency key (fixed from our own data and
 * stored before the first call). PayPal refuses a reused one (USER_BUSINESS_ERROR, "Batch with given sender_batch_id
 * already exists", measured 6 Nov) instead of returning the original batch, so a retry reads that batch back
 * through the link inside the error's details.
 */
export async function createPayout(input: {
  senderBatchId: string;
  requestId: string;
  receiverEmail: string;
  amountCents: number;
  note: string;
  senderItemId: string;
  emailSubject: string;
}): Promise<{ payoutBatchId: string; batchStatus: string; debugId?: string }> {
  try {
    const { body, debugId } = await rest<PayoutBatch>("POST", "/v1/payments/payouts", {
      requestId: input.requestId,
      body: {
        sender_batch_header: { sender_batch_id: input.senderBatchId, email_subject: input.emailSubject },
        items: [
          {
            recipient_type: "EMAIL",
            amount: { value: toAmount(input.amountCents), currency: "USD" },
            receiver: input.receiverEmail,
            note: input.note,
            sender_item_id: input.senderItemId,
          },
        ],
      },
    });
    return { payoutBatchId: body.batch_header?.payout_batch_id ?? "", batchStatus: body.batch_header?.batch_status ?? "UNKNOWN", debugId };
  } catch (err) {
    const reused = err instanceof PayPalError && err.errorName === "USER_BUSINESS_ERROR" && /sender_batch_id already exists/i.test(err.issue);
    const original = reused ? err.links.find((l) => /\/v1\/payments\/payouts\//.test(l.href)) : undefined;
    if (!original) throw err;
    const batchId = original.href.split("/v1/payments/payouts/")[1]?.split(/[/?]/)[0] ?? "";
    const again = await getPayout(batchId);
    return { ...again, debugId: (err as PayPalError).debugId };
  }
}

export async function getPayout(payoutBatchId: string): Promise<{ payoutBatchId: string; batchStatus: string }> {
  const { body } = await rest<PayoutBatch>("GET", `/v1/payments/payouts/${encodeURIComponent(payoutBatchId)}`);
  return { payoutBatchId: body.batch_header?.payout_batch_id ?? payoutBatchId, batchStatus: body.batch_header?.batch_status ?? "UNKNOWN" };
}

// ---- Invoicing v2 (REST; not in the server SDK) ----
// Invoicing ignores PayPal-Request-Id (measured 6 Nov): idempotency comes from the fixed invoice number we store first,
// a search when PayPal says the number already exists, and sending only drafts. A request ID is still sent (hard rule 4).

interface InvoiceBody {
  id?: string;
  status?: string;
  detail?: { metadata?: { recipient_view_url?: string } };
}

export interface InvoiceState {
  invoiceId: string;
  status: string;
  payUrl: string | null;
}

const invoiceState = (body: InvoiceBody, fallbackId = ""): InvoiceState => ({
  invoiceId: body.id ?? fallbackId,
  status: body.status ?? "UNKNOWN",
  payUrl: body.detail?.metadata?.recipient_view_url ?? null,
});

export async function findInvoiceByNumber(invoiceNumber: string, requestId: string): Promise<InvoiceState | null> {
  const { body } = await rest<{ items?: InvoiceBody[] }>("POST", "/v2/invoicing/search-invoices?page=1&page_size=5&total_required=false", {
    requestId,
    body: { invoice_number: invoiceNumber },
  });
  const hit = body.items?.[0];
  return hit?.id ? getInvoice(hit.id) : null;
}

/** A draft invoice from Second Look for one sibling's share, or the one already created under the same number. */
export async function createInvoice(input: {
  invoiceNumber: string;
  requestId: string;
  recipientName: string;
  recipientEmail: string;
  invoicerEmail: string;
  amountCents: number;
  itemName: string;
  note: string;
}): Promise<InvoiceState> {
  try {
    const { body } = await rest<InvoiceBody>("POST", "/v2/invoicing/invoices", {
      requestId: input.requestId,
      body: {
        detail: {
          invoice_number: input.invoiceNumber,
          currency_code: "USD",
          note: input.note,
          payment_term: { term_type: "DUE_ON_RECEIPT" },
        },
        invoicer: { business_name: "Second Look", email_address: input.invoicerEmail },
        primary_recipients: [{ billing_info: { name: { given_name: input.recipientName }, email_address: input.recipientEmail } }],
        items: [{ name: input.itemName, quantity: "1", unit_amount: { currency_code: "USD", value: toAmount(input.amountCents) }, unit_of_measure: "QUANTITY" }],
      },
    });
    return invoiceState(body);
  } catch (err) {
    if (!(err instanceof PayPalError) || err.issue !== "DUPLICATE_INVOICE_NUMBER") throw err;
    const found = await findInvoiceByNumber(input.invoiceNumber, `${input.requestId.slice(0, 30)}-find`);
    if (!found) throw err;
    return found;
  }
}

/** Sends a draft without an email (the family screen links to PayPal's page instead); anything else is left alone. */
export async function sendInvoice(input: { invoiceId: string; requestId: string }): Promise<InvoiceState> {
  const current = await getInvoice(input.invoiceId);
  if (current.status !== "DRAFT") return current;
  await rest("POST", `/v2/invoicing/invoices/${encodeURIComponent(input.invoiceId)}/send`, {
    requestId: input.requestId,
    body: { send_to_recipient: false, send_to_invoicer: false },
  });
  return getInvoice(input.invoiceId);
}

export async function getInvoice(invoiceId: string): Promise<InvoiceState> {
  const { body } = await rest<InvoiceBody>("GET", `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}`);
  return invoiceState(body, invoiceId);
}

// ---- Webhooks ----

/** Asks PayPal whether a webhook delivery is genuine (the postback check). True only for SUCCESS. */
export async function verifyWebhookSignature(input: { headers: Headers; event: unknown; webhookId: string }): Promise<boolean> {
  const h = (name: string) => input.headers.get(name) ?? "";
  const transmissionId = h("paypal-transmission-id");
  if (!transmissionId) return false;
  const { body } = await rest<{ verification_status?: string }>("POST", "/v1/notifications/verify-webhook-signature", {
    requestId: `verify-${transmissionId}`.slice(0, 38),
    body: {
      auth_algo: h("paypal-auth-algo"),
      cert_url: h("paypal-cert-url"),
      transmission_id: transmissionId,
      transmission_sig: h("paypal-transmission-sig"),
      transmission_time: h("paypal-transmission-time"),
      webhook_id: input.webhookId,
      webhook_event: input.event,
    },
  });
  return body.verification_status === "SUCCESS";
}

// ---- Sandbox balance top-up ----

// PayPal's published sandbox test Visa (developer.paypal.com card testing) with a fictional holder. Used only to top
// up Second Look's own sandbox balance; the app never collects or stores anyone's card.
const SANDBOX_TEST_CARD = {
  number: "4111111111111111",
  expiry: "2030-12",
  security_code: "123",
  name: "Second Look Demo",
  billing_address: { address_line_1: "12 Example Lane", admin_area_2: "Columbus", admin_area_1: "OH", postal_code: "43004", country_code: "US" },
};

/** A card-funded CAPTURE order into Second Look's own account: it captures at create, with no buyer step. */
export async function topUpSandboxBalance(input: { requestId: string; amountCents: number }): Promise<{ orderId: string; status: string }> {
  assertSandbox();
  const { body } = await rest<{ id?: string; status?: string }>("POST", "/v2/checkout/orders", {
    requestId: input.requestId,
    body: {
      intent: "CAPTURE",
      purchase_units: [{ reference_id: "balance-top-up", description: "Second Look sandbox balance top-up", amount: { currency_code: "USD", value: toAmount(input.amountCents) } }],
      payment_source: { card: SANDBOX_TEST_CARD },
    },
  });
  return { orderId: body.id ?? "", status: body.status ?? "UNKNOWN" };
}
